/*!
 * Chirpy 7.6.0 cache-first service worker.
 * Other GET requests stay cache-first. GoatCounter and deny_paths stay on the network.
 * GET /ask/history is the per-visitor transcript. Cache Storage ignores
 * Cache-Control: no-store, so that URL is not read from or written to the cache.
 * skipWaiting and clients.claim let an already installed worker take over.
 * This file is not a network-only worker.
 */
importScripts("./assets/js/data/swconf.js");

const purge = swconf.purge;
const interceptor = swconf.interceptor;

function verifyUrl(url) {
  const requestUrl = new URL(url);
  const requestPath = requestUrl.pathname;

  if (!requestUrl.protocol.startsWith("http")) {
    return false;
  }

  for (const prefix of interceptor.urlPrefixes) {
    if (requestUrl.href.startsWith(prefix)) {
      return false;
    }
  }

  for (const path of interceptor.paths) {
    if (requestPath.startsWith(path)) {
      return false;
    }
  }

  return true;
}

function isAskHistory(url) {
  try {
    const path = new URL(url).pathname.replace(/\/+$/, "") || "/";
    return path === "/ask/history";
  } catch (error) {
    return false;
  }
}

function isNoStore(response) {
  const value = response && response.headers ? response.headers.get("cache-control") || "" : "";
  return /\bno-store\b/i.test(value);
}

self.addEventListener("install", (event) => {
  const caching = purge
    ? Promise.resolve()
    : caches.open(swconf.cacheName).then((cache) => cache.addAll(swconf.resources));
  event.waitUntil(caching.then(() => self.skipWaiting()));
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keyList) =>
        Promise.all(
          keyList.map((key) => {
            if (purge || key !== swconf.cacheName) return caches.delete(key);
            return undefined;
          })
        )
      )
      .then(() => self.clients.claim())
  );
});

self.addEventListener("message", (event) => {
  if (event.data === "SKIP_WAITING") self.skipWaiting();
});

self.addEventListener("fetch", (event) => {
  if (event.request.headers.has("range")) return;

  const url = event.request.url;
  if (purge || event.request.method !== "GET" || !verifyUrl(url) || isAskHistory(url)) return;

  event.respondWith(
    caches.match(event.request).then((cached) => {
      if (cached && !isNoStore(cached)) return cached;
      return fetch(event.request).then((response) => {
        if (!response || isNoStore(response)) return response;
        const copy = response.clone();
        caches.open(swconf.cacheName).then((cache) => {
          cache.put(event.request, copy).catch(() => {});
        });
        return response;
      });
    })
  );
});
